import {readFile} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {digestFile} from './vision-diagnostics.mjs';

export const contractPath = fileURLToPath(new URL('../apps/ipad/FoxTrainingCore/Sources/FoxTestSupport/Resources/private-inputs.contract.json', import.meta.url));
export const inputContract = () => readFile(contractPath, 'utf8').then(JSON.parse);

// Locations stay private. The public contract pins pre-existing bytes, not outputs regenerated by the candidate.
export async function validatePrivateInputs(filename, contract) {
  contract ??= await inputContract();
  const ids = Object.keys(contract.assets);
  if (!filename) throw Error(`FOX_PRIVATE_INPUT_MANIFEST required; missing inputs: ${ids.join(', ')}`);
  const manifest = JSON.parse(await readFile(filename, 'utf8'));
  if (manifest.schema !== 'fox.private_inputs.v1' || !manifest.assets) throw Error('Invalid private input manifest');
  const errors = [], checked = [];
  for (const id of ids.sort()) {
    const value = manifest.assets[id], expected = contract.assets[id];
    try {
      if (!value || !path.isAbsolute(value.path ?? '')) throw Error('missing absolute location');
      if (value.sha256 !== expected.sha256) throw Error('differs from pinned historical input');
      const actual = await digestFile(value.path);
      if (actual.sha256 !== expected.sha256 || actual.bytes !== value.bytes) throw Error('digest or bytes changed');
      checked.push({id, path: value.path, ...actual});
    } catch (error) { errors.push(`${id}: ${error.message}`); }
  }
  for (const id of Object.keys(manifest.assets)) if (!contract.assets[id]) errors.push(`${id}: unclassified input`);
  if (errors.length) throw Error(`Private input preflight failed:\n${errors.join('\n')}`);
  return checked;
}

export async function privateInput(id) {
  const file = process.env.FOX_PRIVATE_INPUT_MANIFEST;
  if (!file) throw Error(`FOX_PRIVATE_INPUT_MANIFEST required for ${id}; not a corpus pass`);
  const manifest = JSON.parse(await readFile(file, 'utf8'));
  const contract = await inputContract();
  const value = manifest.assets?.[id];
  if (!value || value.sha256 !== contract.assets[id]?.sha256 || !path.isAbsolute(value.path)) throw Error(`Invalid private input ${id}`);
  const actual = await digestFile(value.path);
  if (actual.sha256 !== value.sha256 || actual.bytes !== value.bytes) throw Error(`Private input changed: ${id}`);
  return value.path;
}
